-- ================================================================
-- DONNÉES TEST MODULE GAZ — bw_samar
-- Comble les gaps pour la plage 2026-04-12 → 2026-05-12
-- Devices : 10, 11, 12, 3001, 6201, 6202
-- ================================================================

USE bw_samar;

-- ── archive_gm_j : Device 10 (Apr 14 → May 11, avg ~1000 L/jour) ──
ON DUPLICATE KEY UPDATE conso=VALUES(conso), `index`=VALUES(`index`), avg_debit_per_min=VALUES(avg_debit_per_min);

-- ── archive_gm_j : Device 11 (Apr 14 → May 11, avg ~700 L/jour) ──
ON DUPLICATE KEY UPDATE conso=VALUES(conso), `index`=VALUES(`index`), avg_debit_per_min=VALUES(avg_debit_per_min);

-- ── archive_gm_j : Device 12 (Apr 14 → May 11, avg ~240 L/jour) ──
ON DUPLICATE KEY UPDATE conso=VALUES(conso), `index`=VALUES(`index`), avg_debit_per_min=VALUES(avg_debit_per_min);

-- ── archive_gm_j : Device 6201 (Apr 12 → May 11, avg ~1200 L/jour) ──
ON DUPLICATE KEY UPDATE conso=VALUES(conso), `index`=VALUES(`index`), avg_debit_per_min=VALUES(avg_debit_per_min);

-- ── archive_gm_j : Device 6202 (Apr 12 → May 11, avg ~2200 L/jour) ──
ON DUPLICATE KEY UPDATE conso=VALUES(conso), `index`=VALUES(`index`), avg_debit_per_min=VALUES(avg_debit_per_min);

-- ── archive_gm_j : Device 3001 (Apr 12 → May 11, avg ~15 L/jour) ──
ON DUPLICATE KEY UPDATE conso=VALUES(conso), `index`=VALUES(`index`), avg_debit_per_min=VALUES(avg_debit_per_min);

-- ── archive_gm_m : mois Avril & Mai 2026 pour tous les devices ───
ON DUPLICATE KEY UPDATE conso=VALUES(conso), `index`=VALUES(`index`);

-- ── rt_gm : mise à jour date + debit pour refléter l'état actuel ─
UPDATE rt_gm SET date='2026-05-12 08:00:00', `index`=152784, avg_debit_per_min=9.2  WHERE id_device=10;
UPDATE rt_gm SET date='2026-05-12 08:00:00', `index`=102495, avg_debit_per_min=11.5 WHERE id_device=11;
UPDATE rt_gm SET date='2026-05-12 08:00:00', `index`=32514,  avg_debit_per_min=3.8  WHERE id_device=12;
UPDATE rt_gm SET date='2026-05-12 08:00:00', `index`=785,    avg_debit_per_min=0.21 WHERE id_device=3001;
UPDATE rt_gm SET date='2026-05-12 08:00:00', `index`=178230, avg_debit_per_min=2.1  WHERE id_device=6201;
UPDATE rt_gm SET date='2026-05-12 08:00:00', `index`=294450, avg_debit_per_min=2.8  WHERE id_device=6202;

-- ── Vérification finale ───────────────────────────────────────────
SELECT id_device,
       COUNT(*) as nb_jours,
       SUM(conso) as total_conso_L,
       ROUND(SUM(conso)/1000,2) as total_m3
FROM archive_gm_j
WHERE date >= '2026-04-12' AND date <= '2026-05-12'
GROUP BY id_device
ORDER BY id_device;
